        /// (string) - Unity Catalog securable UUID of the rule, and the last segment of `Name`. Never changes,
        /// including when the rule's catalog or schema is renamed
        /// </summary>
        [Input("ruleId")]
        public Input<string>? RuleId { get; set; }

        /// <summary>
        /// Name of the rule within its Unity Catalog schema. Required on create; can be updated
        /// within the same catalog and schema. Get synchronizes this field with the current Unity Catalog
        /// name, also reported in `EffectiveRuleName`
        /// </summary>
        [Input("ruleName")]
        public Input<string>? RuleName { get; set; }

        /// <summary>
        /// The principal whose identity this rule's job runs as, given as a
        /// user email or service-principal application ID. When supplied on
        /// create/update, Lakewatch resolves the principal, records it on the rule, and
        /// creates the delegation to run as that principal — the requester must be
        /// authorized to delegate to it, or the request is rejected. When omitted on
        /// create, the requester's own identity is used. An update whose mask does not
        /// include `RunAsPrincipal` keeps the current identity, and the requester must
        /// still be authorized to delegate to it; an editor who is not must supply a
        /// RunAsPrincipal they can delegate to (for example, their own identity), or
        /// clear it, either of which reassigns the rule. An update whose mask includes
        /// `RunAsPrincipal` but supplies no value clears it: the rule then runs as the
        /// requester, exactly as when it is omitted on create. Reads return the value as
        /// supplied; the identity the rule runs as is reported in
        /// `EffectiveRunAsPrincipal`
        /// </summary>
        [Input("runAsPrincipal")]
        public Input<string>? RunAsPrincipal { get; set; }

        /// <summary>
        /// Long-form operational guidance carried from the authored rule metadata. Supports up to 4096
        /// characters. Requests exceeding this limit are rejected. Supports Markdown; analysts and the
        /// investigation agent follow it when triaging this rule's alerts
        /// </summary>
        [Input("runbook")]
        public Input<string>? Runbook { get; set; }

        /// <summary>
        /// When the rule executes
        /// </summary>
        [Input("schedule")]
        public Input<Inputs.LakewatchRuleScheduleGetArgs>? Schedule { get; set; }

        /// <summary>
        /// Name of the Unity Catalog schema that contains the rule. Required. Cannot be changed after
        /// creation. Reads return the value as supplied; the schema's current name is reported in
        /// `EffectiveSchemaName`
        /// </summary>
        [Input("schemaName")]
        public Input<string>? SchemaName { get; set; }

        /// <summary>
        /// Free-form severity label, such as `Informational`, `Medium`, `High`, or
        /// `Critical`
        /// </summary>
        [Input("severity")]
        public Input<string>? Severity { get; set; }

        /// <summary>
        /// (ResourceStatus) - Read-only lifecycle status
        /// </summary>
        [Input("status")]
        public Input<Inputs.LakewatchRuleStatusGetArgs>? Status { get; set; }

        /// <summary>
        /// If set, this rule's signals do not open new alerts until the given time
        /// </summary>
        [Input("suppressUntilTime")]
        public Input<string>? SuppressUntilTime { get; set; }

        /// <summary>
        /// Time-range configuration for scheduled detections. If unset, the execution time range is
        /// extended by a fixed `15m` lookback
        /// </summary>
        [Input("timerange")]
        public Input<Inputs.LakewatchRuleTimerangeGetArgs>? Timerange { get; set; }

        /// <summary>
        /// (string) - Time the rule was last updated
        /// </summary>
        [Input("updateTime")]
        public Input<string>? UpdateTime { get; set; }

        /// <summary>
        /// (Principal) - Principal that last updated the rule
        /// </summary>
        [Input("updatedBy")]
        public Input<Inputs.LakewatchRuleUpdatedByGetArgs>? UpdatedBy { get; set; }

        /// <summary>
        /// (string) - Pack version the resource was installed from
        /// </summary>
        [Input("version")]
        public Input<int>? Version { get; set; }

        public LakewatchRuleState()
        {
        }
        public static new LakewatchRuleState Empty => new LakewatchRuleState();
    }
}
